INSERT INTO "faq" ("id", "question", "answer", "category", "created_at", "updated_at", "created_by") VALUES (3, 'How can I view my contribution history?', 'Log in to your account and navigate to your Dashboard. The Community Events section shows your contribution history, total contributions, and pending contributions.', 'Account', '2026-08-19 11:21:17.880681+03:00', '2026-08-19 11:21:17.880681+03:00', 1);
INSERT INTO "faq" ("id", "question", "answer", "category", "created_at", "updated_at", "created_by") VALUES (1, 'What is Gamerock Welfare Association?', 'Gamerock Welfare Association is a community-based organization dedicated to supporting members through welfare programs, community events, and collective contribution initiatives.', NULL, '2026-08-19 11:21:17.880681+03:00', '2026-08-20 13:44:32.444161+03:00', 1);
INSERT INTO "faq" ("id", "question", "answer", "category", "created_at", "updated_at", "created_by") VALUES (2, 'How do I make contributions?', 'You can make contributions through your dashboard by navigating to the Deposits section. We accept various payment methods including cash, M-PESA, and bank deposits.', 'Contributions', '2026-08-19 11:21:17.880681+03:00', '2026-08-23 18:48:35.212774+03:00', 1);
INSERT INTO "faq" ("id", "question", "answer", "category", "created_at", "updated_at", "created_by") VALUES (5, 'How do I contact support?', 'You can reach us via email at gamerock2026@gmail.com or call us at +254 745908682. Our office is located in Nyeri, Kenya at Gamerock Shopping Center.', 'Support', '2026-08-19 11:21:17.880681+03:00', '2026-08-23 20:21:15.592692+03:00', 1);
INSERT INTO "faq" ("id", "question", "answer", "category", "created_at", "updated_at", "created_by") VALUES (4, 'Who can join Gamerock Welfare Association?', 'Any community member can join. Registration is Ksh. 3500 and open to all. Contact our administrators to get started with your membership.', 'Membership', '2026-08-19 11:21:17.880681+03:00', '2026-09-04 08:55:23.841540+03:00', 1);
