INSERT INTO "minutes" ("id", "title", "meeting_type", "meeting_date", "location", "agenda", "discussion", "decisions", "action_items", "next_meeting_date", "attendees", "status", "approved_by", "approved_at", "created_by", "created_at", "updated_at") VALUES (3, 'March 2026 Emergency Session', 'Emergency', '2026-08-21', 'Community Hall', 'Urgent welfare support case.', 'Discussed urgent member support request and emergency fund eligibility.', 'Approved emergency welfare disbursement. Agreed to review policy next quarter.', 'Treasurer to process disbursement within 48 hours. Secretary to notify member.', '2026-08-31', 'Core committee', 'Approved', 16, '2026-08-26 09:40:36.748790+03:00', 16, '2026-08-06 09:40:36.748790+03:00', '2026-08-26 12:40:36.740066+03:00');
